begin;insert into public.security_permissions(codigo,modulo,nome,criticidade)values('manager.dashboard.read','bi','Consultar painel gestor','sensivel')on conflict(codigo)do update set nome=excluded.nome;insert into public.security_role_permissions(role_id,permission_id)select r.id,p.id from public.security_roles r join public.security_permissions p on p.codigo='manager.dashboard.read'where r.codigo in('tenant_admin','sector_manager','auditor')on conflict do nothing;create table public.manager_kpi_snapshots(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),reference_month date not null,dimensions jsonb not null,metrics jsonb not null,source_checksum text not null,generated_at timestamptz default now(),check(source_checksum~'^[0-9a-f]{64}$'),unique(tenant_id,reference_month,dimensions));alter table public.manager_kpi_snapshots enable row level security;do $$begin if to_regnamespace('auth')is not null then create policy manager_kpis on public.manager_kpi_snapshots for select to authenticated using(private.has_tenant_permission(tenant_id,'manager.dashboard.read'));end if;end$$;revoke all on public.manager_kpi_snapshots from anon;do $$begin if exists(select 1 from pg_roles where rolname='authenticated')then grant select on public.manager_kpi_snapshots to authenticated;end if;end$$;commit;
